// Walks up to the first ancestor that clips overflow (a modal, a scroll pane,
// a card with overflow-hidden). That box, not the viewport, is what would crop
// the suggestion list, so it decides whether the list opens up or down. Only
// overflow-y counts — the list grows vertically, and a box clipping just
// sideways (overflow-x: clip) leaves it free to hang below.
const getClippingRect = (el: HTMLElement): DOMRect | null => {
  let node = el.parentElement;
  while (node && node !== document.body) {
    const { overflowY } = window.getComputedStyle(node);
    if (/(auto|scroll|hidden|clip)/.test(overflowY)) {
      return node.getBoundingClientRect();
    }
    node = node.parentElement;
  }
  return null;
};

// Sets the value the way React expects for both controlled and uncontrolled
// inputs: through the native setter, then an `input` event so React's own
// onChange runs. Assigning `input.value` directly would be swallowed by
// React's value tracker and the consumer would never hear about it.
const writeInputValue = (input: HTMLInputElement, value: string) => {
  const setter = Object.getOwnPropertyDescriptor(
    HTMLInputElement.prototype,
    "value",
  )?.set;
  setter?.call(input, value);
  input.dispatchEvent(new Event("input", { bubbles: true }));
};

/** The suggestion with the typed characters picked out. */
function SuggestionText({
  text,
  query,
  matchClassName,
}: {
  text: string;
  query: string;
  matchClassName: string;
}) {
  const q = query.trim();
  const at = q ? text.toLowerCase().indexOf(q.toLowerCase()) : -1;
  if (at < 0) return <>{text}</>;
  return (
    <>
      {text.slice(0, at)}
      <span className={cn("font-semibold", matchClassName)}>
        {text.slice(at, at + q.length)}
      </span>
      {text.slice(at + q.length)}
    </>
  );
}

export const InputBlock = forwardRef<HTMLInputElement, InputBlockProps>(
  (
    {
      type = "text",
      variant = "default",
      color = "primary",
      inputSize = "md",
      label,
      helperText,
      error,
      leftIcon,
      rightIcon,
      disabled = false,
      className,
      multiple,
      accept,
      onFilesChange,
      suggestions,
      onSuggestionSelect,
      maxSuggestions = 8,
      ...props
    },
    ref,
  ) => {
    const [showPassword, setShowPassword] = useState(false);
    const { theme, style } = getThemeStyles(color);
    const hasError = Boolean(error);

    // --- Autocomplete State ---
    const hasSuggestions =
      Boolean(suggestions?.length) && type !== "file" && type !== "password";
    const inputRef = useRef<HTMLInputElement | null>(null);
    const fieldRef = useRef<HTMLDivElement>(null);
    const listRef = useRef<HTMLUListElement>(null);
    const listId = useId();
    const [listOpen, setListOpen] = useState(false);
    const [listUp, setListUp] = useState(false);
    const [activeIndex, setActiveIndex] = useState(-1);
    // Mirror of what is in the field. For a controlled input this is
    // `props.value`; otherwise it tracks the native input as the user types.
    const [typed, setTyped] = useState(String(props.defaultValue ?? ""));
    const query =
      props.value !== undefined ? String(props.value) : typed;

    const assignInputRef = (node: HTMLInputElement | null) => {
      inputRef.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;
    };

    const matches = hasSuggestions
      ? (suggestions as string[])
          .filter((item) =>
            item.toLowerCase().includes(query.trim().toLowerCase()),
          )
          .slice(0, maxSuggestions)
      : [];

    const closeList = () => {
      setListOpen(false);
      setActiveIndex(-1);
    };

    const chooseSuggestion = (item: string) => {
      const input = inputRef.current;
      if (input) {
        writeInputValue(input, item);
        input.focus();
      }
      setTyped(item);
      onSuggestionSelect?.(item);
      closeList();
    };

    // Open upward only when the clipping box has no room below and more above.
    // Measured before paint so the list never appears on the wrong side first.
    useLayoutEffect(() => {
      if (!listOpen || !fieldRef.current) return;
      const trigger = fieldRef.current.getBoundingClientRect();
      const clip = getClippingRect(fieldRef.current);
      const listHeight = listRef.current?.offsetHeight ?? 240;
      const bottomBound = Math.min(
        window.innerHeight,
        clip ? clip.bottom : Number.POSITIVE_INFINITY,
      );
      const topBound = Math.max(0, clip ? clip.top : 0);
      const spaceBelow = bottomBound - trigger.bottom - 8;
      const spaceAbove = trigger.top - topBound - 8;
      setListUp(spaceBelow < listHeight && spaceAbove > spaceBelow);
    }, [listOpen, matches.length]);

    // Keep the keyboard-highlighted row in view inside the scrolling list.
    useEffect(() => {
      if (activeIndex < 0) return;
      listRef.current
        ?.querySelector<HTMLElement>(`[data-index="${activeIndex}"]`)
        ?.scrollIntoView({ block: "nearest" });
    }, [activeIndex]);

    // Click outside closes the list.
    useEffect(() => {
      if (!listOpen) return;
      const onPointerDown = (e: MouseEvent) => {
        if (!fieldRef.current?.contains(e.target as Node)) closeList();
      };
      document.addEventListener("mousedown", onPointerDown);
      return () => document.removeEventListener("mousedown", onPointerDown);
    }, [listOpen]);

    const handleSuggestionKeyDown = (
      e: React.KeyboardEvent<HTMLInputElement>,
    ) => {
      props.onKeyDown?.(e);
      if (e.defaultPrevented || !hasSuggestions) return;

      if (e.key === "ArrowDown") {
        e.preventDefault();
        if (!listOpen) setListOpen(true);
        if (matches.length)
          setActiveIndex((i) => (i + 1) % matches.length);
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        if (!listOpen) setListOpen(true);
        if (matches.length)
          setActiveIndex((i) => (i <= 0 ? matches.length - 1 : i - 1));
      } else if (e.key === "Enter") {
        if (listOpen && activeIndex >= 0 && matches[activeIndex]) {
          e.preventDefault();
          chooseSuggestion(matches[activeIndex]);
        }
      } else if (e.key === "Escape") {
        if (listOpen) {
          e.preventDefault();
          closeList();
        }
      } else if (e.key === "Tab") {
        closeList();
      }
    };

    // --- File Upload State ---
    const [isDragging, setIsDragging] = useState(false);
    const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
    const [previews, setPreviews] = useState<Record<string, string>>({});
    const fileInputRef = useRef<HTMLInputElement>(null);

    // --- Size Classes ---
    const sizeClasses = {
      sm: {
        wrapper: "min-h-9 px-3",
        text: "text-xs",
        icon: "w-3.5 h-3.5",
        dropzone: "p-4 min-h-[100px]",
      },
      md: {
        wrapper: "min-h-11 px-4",
        text: "text-sm",
        icon: "w-4 h-4",
        dropzone: "p-6 min-h-[140px]",
      },
      lg: {
        wrapper: "min-h-14 px-5",
        text: "text-base",
        icon: "w-5 h-5",
        dropzone: "p-8 min-h-[180px]",
      },
    };
    const s = sizeClasses[inputSize];

    // --- Variant Styles ---
    const getVariantStyles = () => {
      const baseWrapper = cn(
        "relative flex items-center w-full transition-all duration-300 overflow-hidden",
        s.wrapper,
      );

      if (disabled)
        return {
          wrapper: cn(
            baseWrapper,
            "opacity-50 cursor-not-allowed border border-border bg-muted",
          ),
          active: "",
        };
      if (hasError)
        return {
          wrapper: cn(
            baseWrapper,
            "border border-red-500 bg-background",
            variant === "underlined" && "border-0 border-b-2 rounded-none",
            variant !== "underlined" && "rounded-xl",
          ),
          active: "focus-within:ring-4 focus-within:ring-red-500/10",
        };

      switch (variant) {
        case "filled":
          return {
            wrapper: cn(
              baseWrapper,
              "bg-muted border border-transparent rounded-xl",
            ),
            active: cn(
              "focus-within:bg-background focus-within:ring-4",
              theme.ring,
            ),
          };
        case "underlined":
          return {
            wrapper: cn(
              baseWrapper,
              "border-b-2 border-border bg-transparent rounded-none px-0",
            ),
            active: theme.ring,
          };
        case "glow":
          return {
            wrapper: cn(
              baseWrapper,
              "bg-background border border-border rounded-xl shadow-sm",
            ),
            active: theme.glow,
          };
        case "default":
        default:
          return {
            wrapper: cn(
              baseWrapper,
              "bg-background border border-border rounded-xl shadow-sm",
            ),
            active: cn("focus-within:ring-4", theme.ring),
          };
      }
    };
    const styles = getVariantStyles();

    // ==========================================
    // FILE UPLOAD LOGIC
    // ==========================================
    const formatFileSize = (bytes: number) => {
      if (bytes === 0) return "0 Bytes";
      const k = 1024;
      const sizes = ["Bytes", "KB", "MB", "GB"];
      const i = Math.floor(Math.log(bytes) / Math.log(k));
      return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i];
    };

    const processFiles = useCallback(
      (newFiles: File[]) => {
        const first = newFiles[0];
        const validFiles = multiple
          ? [...selectedFiles, ...newFiles]
          : first
            ? [first]
            : [];
        setSelectedFiles(validFiles);
        if (onFilesChange) onFilesChange(validFiles);

        // Generate previews for images
        validFiles.forEach((file) => {
          if (file.type.startsWith("image/") && !previews[file.name]) {
            const reader = new FileReader();
            reader.onloadend = () => {
              setPreviews((prev) => ({
                ...prev,
                [file.name]: reader.result as string,
              }));
            };
            reader.readAsDataURL(file);
          }
        });
      },
      [multiple, selectedFiles, previews, onFilesChange],
    );

    const handleDragOver = (e: React.DragEvent) => {
      e.preventDefault();
      setIsDragging(true);
    };
    const handleDragLeave = (e: React.DragEvent) => {
      e.preventDefault();
      setIsDragging(false);
    };
    const handleDrop = (e: React.DragEvent) => {
      e.preventDefault();
      setIsDragging(false);
      if (disabled) return;
      if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
        processFiles(Array.from(e.dataTransfer.files));
      }
    };
    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0) {
        processFiles(Array.from(e.target.files));
      }
    };
    const removeFile = (fileName: string, e: React.MouseEvent) => {
      e.stopPropagation();
      const updatedFiles = selectedFiles.filter((f) => f.name !== fileName);
      setSelectedFiles(updatedFiles);
      if (onFilesChange) onFilesChange(updatedFiles);
      setPreviews((prev) => {
        const newPreviews = { ...prev };
        delete newPreviews[fileName];
        return newPreviews;
      });
    };

    // ==========================================
    // RENDER: FILE TYPE
    // ==========================================
    if (type === "file") {
      return (
        <div
          className={cn("flex flex-col gap-1.5 w-full relative", className)}
          style={style}
        >
          {label && (
            <label
              className={cn(
                "text-sm font-semibold",
                hasError ? "text-red-500" : "text-foreground",
                disabled && "opacity-50",
              )}
            >
              {label}
            </label>
          )}

          <div
            onClick={() => !disabled && fileInputRef.current?.click()}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            className={cn(
              "w-full border-2 border-dashed rounded-xl flex flex-col items-center justify-center text-center cursor-pointer transition-all duration-200 ease-in-out group",
              s.dropzone,
              disabled
                ? "opacity-50 cursor-not-allowed border-border bg-muted"
                : hasError
                  ? "border-red-400 bg-red-50/50 dark:bg-red-500/5"
                  : isDragging
                    ? theme.dragActive
                    : "border-border bg-muted/50 hover:bg-muted",
            )}
          >
            <input
              type="file"
              ref={fileInputRef}
              className="hidden"
              multiple={multiple}
              accept={accept}
              onChange={handleFileChange}
              disabled={disabled}
              {...props}
            />
            <div
              className={cn(
                "p-3 rounded-full mb-3 transition-colors",
                isDragging
                  ? theme.bg
                  : "bg-card shadow-sm border border-border group-hover:scale-105",
              )}
            >
              <UploadCloud
                className={cn(
                  "w-6 h-6",
                  !isDragging && theme.text,
                )}
              />
            </div>
            <p
              className={cn("font-semibold text-foreground", s.text)}
            >
              {isDragging
                ? "Drop files here"
                : "Click or drag file to this area"}
            </p>
            <p className="text-xs text-muted-foreground mt-1 max-w-[250px]">
              {accept ? `Supports ${accept}` : "Supports all file types"}{" "}
              {multiple && "• Upload multiple"}
            </p>
          </div>

          {/* File List / Previews */}
          {selectedFiles.length > 0 && (
            <div className="flex flex-col gap-2 mt-2">
              {selectedFiles.map((file) => (
                <div
                  key={file.name}
                  className="flex items-center justify-between p-3 bg-card border border-border rounded-lg shadow-sm group"
                >
                  <div className="flex items-center gap-3 overflow-hidden">
                    {previews[file.name] ? (
                      <div className="w-10 h-10 shrink-0 rounded-md overflow-hidden bg-muted relative border border-border">
                        {/* A FileReader data URL — next/image cannot optimise
                            it and would need `unoptimized`, so a plain img is
                            both simpler and framework-neutral. */}
                        <img
                          src={previews[file.name]}
                          alt="preview"
                          className="absolute inset-0 h-full w-full object-cover"
                        />
                      </div>
                    ) : (
                      <div
                        className={cn(
                          "w-10 h-10 shrink-0 rounded-md flex items-center justify-center",
                          theme.bgSoft,
                        )}
                      >
                        {file.type.includes("pdf") ? (
                          <FileText className={cn("w-5 h-5", theme.text)} />
                        ) : (
                          <FileIcon className={cn("w-5 h-5", theme.text)} />
                        )}
                      </div>
                    )}
                    <div className="flex flex-col min-w-0">
                      <span className="text-sm font-semibold text-foreground truncate">
                        {file.name}
                      </span>
                      <span className="text-xs text-muted-foreground font-medium">
                        {formatFileSize(file.size)}
                      </span>
                    </div>
                  </div>
                  <button
                    type="button"
                    onClick={(e) => removeFile(file.name, e)}
                    className="p-2 shrink-0 rounded-md text-muted-foreground hover:bg-red-50 hover:text-red-500 dark:hover:bg-red-500/10 transition-colors"
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>
              ))}
            </div>
          )}

          {error && (
            <p className="text-xs font-semibold text-red-500 flex items-center gap-1 mt-0.5">
              <AlertCircle className="w-3.5 h-3.5" /> {error}
            </p>
          )}
          {helperText && !error && (
            <p className="text-xs font-medium text-muted-foreground mt-0.5">
              {helperText}
            </p>
          )}
        </div>
      );
    }

    // ==========================================
    // RENDER: STANDARD TEXT/PASSWORD/EMAIL
    // ==========================================
    const isPassword = type === "password";
    const inputType = isPassword ? (showPassword ? "text" : "password") : type;

    return (
      <div
        className={cn("flex flex-col gap-1.5 w-full relative", className)}
        style={style}
      >
        {label && (
          <label
            className={cn(
              "text-sm font-semibold",
              hasError ? "text-red-500" : "text-foreground",
              disabled && "opacity-50",
            )}
          >
            {label}
          </label>
        )}

        <div
          ref={fieldRef}
          className={cn("relative", hasSuggestions && "z-10")}
        >
        <div className={cn(styles.wrapper, styles.active)}>
          {leftIcon && (
            <div
              className={cn(
                "shrink-0 pl-4 text-muted-foreground",
                variant === "underlined" && "pl-0 pr-3",
              )}
            >
              {leftIcon}
            </div>
          )}

          <input
            ref={assignInputRef}
            type={inputType}
            disabled={disabled}
            className={cn(
              "w-full h-full bg-transparent border-none outline-none text-foreground placeholder:text-muted-foreground/70 transition-colors",
              s.text,
              leftIcon && variant !== "underlined" ? "pl-2.5" : "pl-0",
              variant === "underlined" && !leftIcon && "pl-0",
              rightIcon || isPassword ? "pr-2.5" : "pr-0",
            )}
            {...props}
            {...(hasSuggestions
              ? {
              role: "combobox",
              autoComplete: "off",
              "aria-autocomplete": "list",
              "aria-expanded": listOpen && matches.length > 0,
              "aria-controls": listId,
              "aria-activedescendant":
                listOpen && activeIndex >= 0
                  ? `${listId}-${activeIndex}`
                  : undefined,
              onChange: (e: React.ChangeEvent<HTMLInputElement>) => {
                props.onChange?.(e);
                setTyped(e.target.value);
                setActiveIndex(-1);
                if (!listOpen) setListOpen(true);
              },
              onFocus: (e: React.FocusEvent<HTMLInputElement>) => {
                props.onFocus?.(e);
                setListOpen(true);
              },
              onKeyDown: handleSuggestionKeyDown,
                }
              : {})}
          />

          {isPassword && (
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              disabled={disabled}
              className={cn(
                "shrink-0 pr-4 text-muted-foreground hover:text-muted-foreground transition-colors disabled:opacity-50",
                variant === "underlined" && "pr-0 pl-3",
              )}
            >
              {showPassword ? (
                <EyeOff className={s.icon} />
              ) : (
                <Eye className={s.icon} />
              )}
            </button>
          )}
          {rightIcon && !isPassword && (
            <div
              className={cn(
                "shrink-0 pr-4 text-muted-foreground",
                variant === "underlined" && "pr-0 pl-3",
              )}
            >
              {rightIcon}
            </div>
          )}
        </div>

        {/* Suggestion list. Rows are chosen on mousedown so the field keeps
            focus; the native `input` event then runs the consumer's onChange. */}
        {hasSuggestions && listOpen && !disabled && (
          <ul
            ref={listRef}
            id={listId}
            role="listbox"
            aria-label={label ? `${label} suggestions` : "Suggestions"}
            className={cn(
              "absolute left-0 right-0 z-50 max-h-[18.5rem] overflow-y-auto p-1 border border-border bg-popover text-popover-foreground rounded-xl shadow-lg",
              "animate-in fade-in duration-150",
              listUp
                ? cn(
                    "origin-bottom slide-in-from-bottom-1",
                    variant === "underlined"
                      ? "bottom-[100%]"
                      : "bottom-[calc(100%+6px)]",
                  )
                : cn(
                    "origin-top slide-in-from-top-1",
                    variant === "underlined"
                      ? "top-[100%]"
                      : "top-[calc(100%+6px)]",
                  ),
            )}
          >
            {matches.length === 0 ? (
              <li className="px-3 py-2.5 text-xs text-muted-foreground">
                No matches for{" "}
                <span className="font-medium text-foreground">
                  &ldquo;{query.trim()}&rdquo;
                </span>
                {" "}— keep typing to use it as-is.
              </li>
            ) : (
              matches.map((item, index) => {
                const isActive = index === activeIndex;
                return (
                  <li
                    key={item}
                    id={`${listId}-${index}`}
                    data-index={index}
                    role="option"
                    aria-selected={isActive}
                    onMouseDown={(e) => {
                      e.preventDefault();
                      chooseSuggestion(item);
                    }}
                    onMouseEnter={() => setActiveIndex(index)}
                    className={cn(
                      "flex items-center justify-between gap-3 px-3 py-2 rounded-lg cursor-pointer text-foreground",
                      s.text,
                      isActive ? theme.bgSoft : "hover:bg-muted/60",
                    )}
                  >
                    <span className="truncate">
                      <SuggestionText
                        text={item}
                        query={query}
                        matchClassName={theme.text}
                      />
                    </span>
                    {isActive && (
                      <CornerDownLeft
                        aria-hidden
                        className={cn("w-3.5 h-3.5 shrink-0", theme.text)}
                      />
                    )}
                  </li>
                );
              })
            )}
          </ul>
        )}
        </div>

        {error && (
          <p className="text-xs font-semibold text-red-500 flex items-center gap-1 mt-0.5">
            <AlertCircle className="w-3.5 h-3.5" /> {error}
          </p>
        )}
        {helperText && !error && (
          <p className="text-xs font-medium text-muted-foreground mt-0.5">
            {helperText}
          </p>
        )}
      </div>
    );
  },
);
InputBlock.displayName = "InputBlock";

"use client";

import React from "react";

/** The class set one colour gives the block. */
export interface InputTheme {
  ring: string;
  text: string;
  bg: string;
  bgSoft: string;
  glow: string;
  dragActive: string;
}

const PRIMARY: InputTheme = {
  ring: "focus-within:ring-primary/25 focus-within:border-primary",
  text: "text-primary",
  bg: "bg-primary text-primary-foreground",
  bgSoft: "bg-primary/10 text-foreground",
  glow: "focus-within:shadow-[0_0_20px_var(--primary)] focus-within:border-primary",
  dragActive: "border-primary bg-primary/10",
};

const colorThemes: Record<string, InputTheme> = {
  primary: PRIMARY,
  lavender: {
    ring: "focus-within:ring-[#9b8afb]/30 focus-within:border-[#9b8afb]",
    text: "text-[#9b8afb]",
    bg: "bg-[#9b8afb] text-white",
    bgSoft:
      "bg-[#9b8afb]/10 text-[#9b8afb]",
    glow: "focus-within:shadow-[0_0_20px_rgba(155,138,251,0.4)] focus-within:border-[#9b8afb]",
    dragActive: "border-[#9b8afb] bg-[#9b8afb]/10",
  },
  indigo: {
    ring: "focus-within:ring-indigo-500/30 focus-within:border-indigo-500",
    text: "text-indigo-600 dark:text-indigo-400",
    bg: "bg-indigo-600 text-white",
    bgSoft:
      "bg-indigo-50 dark:bg-indigo-500/10 text-indigo-900 dark:text-indigo-100",
    glow: "focus-within:shadow-[0_0_20px_rgba(99,102,241,0.4)] focus-within:border-indigo-500",
    dragActive: "border-indigo-500 bg-indigo-50 dark:bg-indigo-500/10",
  },
  rose: {
    ring: "focus-within:ring-rose-500/30 focus-within:border-rose-500",
    text: "text-rose-600 dark:text-rose-400",
    bg: "bg-rose-600 text-white",
    bgSoft: "bg-rose-50 dark:bg-rose-500/10 text-rose-900 dark:text-rose-100",
    glow: "focus-within:shadow-[0_0_20px_rgba(244,63,94,0.4)] focus-within:border-rose-500",
    dragActive: "border-rose-500 bg-rose-50 dark:bg-rose-500/10",
  },
  emerald: {
    ring: "focus-within:ring-emerald-500/30 focus-within:border-emerald-500",
    text: "text-emerald-600 dark:text-emerald-400",
    bg: "bg-emerald-600 text-white",
    bgSoft:
      "bg-emerald-50 dark:bg-emerald-500/10 text-emerald-900 dark:text-emerald-100",
    glow: "focus-within:shadow-[0_0_20px_rgba(16,185,129,0.4)] focus-within:border-emerald-500",
    dragActive: "border-emerald-500 bg-emerald-50 dark:bg-emerald-500/10",
  },
  zinc: {
    ring: "focus-within:ring-zinc-500/30 focus-within:border-zinc-500 dark:focus-within:ring-white/20 dark:focus-within:border-white",
    text: "text-zinc-900 dark:text-zinc-100",
    bg: "bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900",
    bgSoft: "bg-zinc-100 dark:bg-zinc-800/50 text-zinc-900 dark:text-zinc-100",
    glow: "focus-within:shadow-[0_0_20px_rgba(255,255,255,0.15)] focus-within:border-zinc-900 dark:focus-within:border-white",
    dragActive:
      "border-zinc-900 dark:border-zinc-100 bg-zinc-100 dark:bg-zinc-800/50",
  },
};

const hexToRgb = (hex: string) => {
  let cleanHex = hex.replace(/^#/, "");
  if (cleanHex.length === 3)
    cleanHex = cleanHex
      .split("")
      .map((x) => x + x)
      .join("");
  const result = /^([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(cleanHex);
  return result
    ? `${parseInt(result[1] ?? "63", 16)}, ${parseInt(result[2] ?? "66", 16)}, ${parseInt(result[3] ?? "f1", 16)}`
    : "99, 102, 241";
};

export const getThemeStyles = (color: string): { theme: InputTheme; style: React.CSSProperties } => {
  if (color && color.startsWith("#")) {
    const rgb = hexToRgb(color);
    return {
      theme: {
        ring: "focus-within:ring-[var(--theme-color)]/30 focus-within:border-[var(--theme-color)]",
        text: "text-[var(--theme-color)]",
        bg: "bg-[var(--theme-color)] text-white hover:opacity-90",
        bgSoft:
          "bg-[rgba(var(--theme-color-rgb),0.1)] text-[var(--theme-color)]",
        glow: "focus-within:shadow-[0_0_20px_rgba(var(--theme-color-rgb),0.5)] focus-within:border-[var(--theme-color)]",
        dragActive:
          "border-[var(--theme-color)] bg-[rgba(var(--theme-color-rgb),0.05)]",
      },
      style: {
        "--theme-color": color,
        "--theme-color-rgb": rgb,
      } as React.CSSProperties,
    };
  }
  return { theme: colorThemes[color] ?? PRIMARY, style: {} };
};

"use client";

import { cn } from "@/lib/utils";
import React, { forwardRef } from "react";

// ==========================================
// MARQUEE COMPONENT
// ==========================================
export interface MarqueeProps extends React.HTMLAttributes<HTMLDivElement> {
  /** The direction the marquee should slide */
  direction?: "left" | "right" | "up" | "down";
  /** The speed of the marquee. Can be a preset string or a number in seconds */
  speed?: "slow" | "normal" | "fast" | number;
  /** Whether the marquee should pause when hovered */
  pauseOnHover?: boolean;
  /** Whether to apply a gradient fade mask to the edges */
  fade?: boolean;
  /** CSS gap between items (e.g., "1rem", "24px") */
  gap?: string;
  /** The content to be duplicated and animated */
  children: React.ReactNode;
}

export const MarqueeBlock = forwardRef<HTMLDivElement, MarqueeProps>(
  (
    {
      direction = "left",
      speed = "normal",
      pauseOnHover = false,
      fade = false,
      gap = "1rem",
      className,
      children,
      ...props
    },
    ref,
  ) => {
    const isVertical = direction === "up" || direction === "down";
    const isReverse = direction === "right" || direction === "down";

    // Determine animation duration based on speed
    let duration: string;
    if (typeof speed === "number") {
      duration = `${speed}s`;
    } else {
      switch (speed) {
        case "slow":
          duration = "40s";
          break;
        case "fast":
          duration = "10s";
          break;
        case "normal":
        default:
          duration = "20s";
          break;
      }
    }

    const uniqueId = React.useId().replace(/:/g, "");

    const animationName = isVertical
      ? isReverse
        ? `marquee-v-down-${uniqueId}`
        : `marquee-v-up-${uniqueId}`
      : isReverse
        ? `marquee-h-right-${uniqueId}`
        : `marquee-h-left-${uniqueId}`;

    return (
      <div
        ref={ref}
        className={cn(
          "group relative flex overflow-hidden",
          `marquee-container-${uniqueId}`,
          isVertical ? "flex-col" : "flex-row",
          fade && isVertical && "mask-vertical",
          fade && !isVertical && "mask-horizontal",
          className,
        )}
        style={
          {
            "--marquee-gap": gap,
            "--marquee-duration": duration,
            gap: gap,
          } as React.CSSProperties
        }
        {...props}
      >
        <style>{`
          .marquee-inner-${uniqueId} {
            display: flex;
            flex-shrink: 0;
            justify-content: flex-start;
            gap: var(--marquee-gap);
            will-change: transform;
            transform: translateZ(0);
            backface-visibility: hidden;
            animation: ${animationName} var(--marquee-duration) linear infinite;
          }

          /* Instant smooth pause without jumping or browser matrix snap */
          ${pauseOnHover ? `
            .marquee-container-${uniqueId}:hover .marquee-inner-${uniqueId},
            .marquee-inner-${uniqueId}:hover {
              animation-play-state: paused !important;
            }
          ` : ""}

          /* Hold still for people who asked for less motion */
          @media (prefers-reduced-motion: reduce) {
            .marquee-inner-${uniqueId} { animation-play-state: paused !important; }
          }

          /* Leftward scroll: from 0 to -100% */
          @keyframes marquee-h-left-${uniqueId} {
            from { transform: translate3d(0, 0, 0); }
            to { transform: translate3d(calc(-100% - var(--marquee-gap)), 0, 0); }
          }

          /* Rightward scroll: from -100% to 0, running forward so pause never jumps! */
          @keyframes marquee-h-right-${uniqueId} {
            from { transform: translate3d(calc(-100% - var(--marquee-gap)), 0, 0); }
            to { transform: translate3d(0, 0, 0); }
          }

          /* Vertical up scroll */
          @keyframes marquee-v-up-${uniqueId} {
            from { transform: translate3d(0, 0, 0); }
            to { transform: translate3d(0, calc(-100% - var(--marquee-gap)), 0); }
          }

          /* Vertical down scroll */
          @keyframes marquee-v-down-${uniqueId} {
            from { transform: translate3d(0, calc(-100% - var(--marquee-gap)), 0); }
            to { transform: translate3d(0, 0, 0); }
          }

          .mask-horizontal {
            mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);
            -webkit-mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);
          }

          .mask-vertical {
            mask-image: linear-gradient(to bottom, transparent, black 10%, black 90%, transparent);
            -webkit-mask-image: linear-gradient(to bottom, transparent, black 10%, black 90%, transparent);
          }
        `}</style>

        {/* Track 1 */}
        <div
          className={cn(
            `marquee-inner-${uniqueId}`,
            isVertical ? "flex-col" : "flex-row",
          )}
          aria-hidden="false"
        >
          {children}
        </div>

        {/* Track 2 (Duplicate for seamless loop) */}
        <div
          className={cn(
            `marquee-inner-${uniqueId}`,
            isVertical ? "flex-col" : "flex-row",
          )}
          aria-hidden="true"
        >
          {children}
        </div>

        {/* Track 3 (Guarantees zero-gap on reverse/rightward scroll and ultra-wide screens) */}
        <div
          className={cn(
            `marquee-inner-${uniqueId}`,
            isVertical ? "flex-col" : "flex-row",
          )}
          aria-hidden="true"
        >
          {children}
        </div>

        {/* Track 4 (Guarantees zero-gap on reverse/rightward scroll and ultra-wide screens) */}
        <div
          className={cn(
            `marquee-inner-${uniqueId}`,
            isVertical ? "flex-col" : "flex-row",
          )}
          aria-hidden="true"
        >
          {children}
        </div>
      </div>
    );
  },
);
MarqueeBlock.displayName = "MarqueeBlock";

"use client";

import { cn } from "@/lib/utils";
import React, { useEffect, useRef } from "react";
import { createSpringFollower, type SpringFollower } from "./motion-curves";

export interface TiltedCardProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
  tiltIntensity?: number; // Maximum rotation in degrees (e.g., 15)
  glareOpacity?: number; // Maximum opacity of the glare effect (0 to 1)
  scaleOnHover?: number; // Scale factor when hovered (e.g., 1.05)
}

// Pointer tilt: every frame the tilt chases the pointer through this spring,
// keeping its velocity when the pointer moves on — no animation library, just
// the spring's equation of motion stepped on requestAnimationFrame.
const TILT_SPRING = { damping: 25, stiffness: 300, mass: 0.5, restDelta: 0.001, restSpeed: 0.01 };
// Hover scale, same approach, so leaving mid-grow springs back from where it is.
const HOVER_SPRING = { stiffness: 300, damping: 20, mass: 1, restDelta: 0.005, restSpeed: 0.01 };

/** Maps -1..1 onto `from..to`, clamped at both ends. */
const mapRange = (v: number, from: number, to: number) => {
  const p = Math.min(Math.max((v + 1) / 2, 0), 1);
  return from + (to - from) * p;
};

const glareBackground = (x: number, y: number) =>
  `radial-gradient(circle at ${x}% ${y}%, var(--theme-color,var(--primary)), transparent 65%)`;

export const TiltedCard = React.forwardRef<HTMLDivElement, TiltedCardProps>(
  (
    {
      children,
      className,
      tiltIntensity = 15,
      glareOpacity = 0.2,
      scaleOnHover = 1.02,
      ...props
    },
    ref,
  ) => {
    const cardRef = useRef<HTMLDivElement>(null);
    const glareRef = useRef<HTMLDivElement>(null);

    React.useImperativeHandle(ref, () => cardRef.current as HTMLDivElement);

    // Read at paint time, so a changed prop applies from the next frame.
    const latest = useRef({ tiltIntensity, scaleOnHover });
    latest.current = { tiltIntensity, scaleOnHover };

    const springs = useRef<{
      x: SpringFollower;
      y: SpringFollower;
      scale: SpringFollower;
    } | null>(null);

    useEffect(() => {
      // Writes the card transform and the glare straight to the DOM, the way
      // motion values do — no React render per frame.
      const paint = () => {
        const s = springs.current;
        const card = cardRef.current;
        if (!s || !card) return;
        const tilt = latest.current.tiltIntensity;
        const x = s.x.get();
        const y = s.y.get();
        const scale = s.scale.get();
        const rotateX = mapRange(y, tilt, -tilt);
        const rotateY = mapRange(x, -tilt, tilt);
        const parts: string[] = [];
        if (scale !== 1) parts.push(`scale(${scale})`);
        if (rotateX !== 0) parts.push(`rotateX(${rotateX}deg)`);
        if (rotateY !== 0) parts.push(`rotateY(${rotateY}deg)`);
        card.style.transform = parts.length ? parts.join(" ") : "none";
        if (glareRef.current) {
          glareRef.current.style.background = glareBackground(
            mapRange(x, 0, 100),
            mapRange(y, 0, 100),
          );
        }
      };

      springs.current = {
        x: createSpringFollower(0, paint, TILT_SPRING),
        y: createSpringFollower(0, paint, TILT_SPRING),
        scale: createSpringFollower(1, paint, HOVER_SPRING),
      };

      return () => {
        springs.current?.x.destroy();
        springs.current?.y.destroy();
        springs.current?.scale.destroy();
        springs.current = null;
      };
    }, []);

    const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
      if (!cardRef.current) return;
      const rect = cardRef.current.getBoundingClientRect();
      const x = (e.clientX - rect.left) / rect.width - 0.5;
      const y = (e.clientY - rect.top) / rect.height - 0.5;
      springs.current?.x.set(x * 2);
      springs.current?.y.set(y * 2);
    };

    const handleMouseLeave = () => {
      springs.current?.x.set(0);
      springs.current?.y.set(0);
    };

    // Hover scale follows a mouse or pen; a touch never counts as hovering.
    const handlePointerEnter = (e: React.PointerEvent<HTMLDivElement>) => {
      if (e.pointerType === "touch") return;
      springs.current?.scale.set(latest.current.scaleOnHover);
    };

    const handlePointerLeave = (e: React.PointerEvent<HTMLDivElement>) => {
      if (e.pointerType === "touch") return;
      springs.current?.scale.set(1);
    };

    return (
      <div
        className={cn("relative perspective-[1000px] w-full h-full", className)}
        {...props}
      >
        <div
          ref={cardRef}
          onMouseMove={handleMouseMove}
          onMouseLeave={handleMouseLeave}
          onPointerEnter={handlePointerEnter}
          onPointerLeave={handlePointerLeave}
          style={{
            transformStyle: "preserve-3d",
          }}
          className="relative w-full h-full rounded-2xl overflow-visible shadow-[0_10px_30px_rgba(0,0,0,0.08)] dark:shadow-[0_10px_30px_rgba(0,0,0,0.5)] transition-shadow duration-300 hover:shadow-[0_20px_40px_rgba(0,0,0,0.14)] dark:hover:shadow-[0_20px_40px_rgba(0,0,0,0.7)] group cursor-pointer"
        >
          <div
            className="relative w-full h-full z-10"
            style={
              {
                transform: "translateZ(30px)",
                "--glare-opacity": glareOpacity,
              } as React.CSSProperties
            }
          >
            {children}

            {/* Dynamic Theme Color Glare Overlay */}
            <div
              ref={glareRef}
              className="absolute inset-0 z-50 pointer-events-none opacity-0 group-hover:opacity-[var(--glare-opacity)] transition-opacity duration-300 rounded-2xl"
              style={{ background: glareBackground(50, 50) }}
            />
          </div>
        </div>
      </div>
    );
  },
);
TiltedCard.displayName = "TiltedCard";
